// Passo 1: a planta — classe com o constructor que recebe nome e turma.
class FichaDeAluno {
  constructor(nome, turma) {
    this.nome = nome;   // campo nome: cada ficha guarda o seu
    this.turma = turma; // campo turma: idem
  }
}

// Passo 2: construindo casas a partir da planta.
const ana = new FichaDeAluno('Ana', '3A');
const bia = new FichaDeAluno('Bia', '3B');

// Passo 3: mesmos campos, valores próprios de cada instância.
console.log(ana.nome);  // imprime: Ana
console.log(bia.nome);  // imprime: Bia
console.log(ana.turma); // imprime: 3A

// Passo 4: a estrutura é garantida — toda ficha tem nome e turma.
console.log(ana instanceof FichaDeAluno); // imprime: true
